import React from 'react';
import {combineReducers} from 'redux';
import {createSlice} from '@reduxjs/toolkit';
import {Menu, ImageUrl} from '../../DataTypes/';

type ActionType = {
    type: string,
    payload: Menu[],
}
type MenuData = {
    status: string,
    data: Menu[]
}
export const menuSlice = createSlice({
    name:'menuList',
    initialState: {status: 'pending',data: [] as Menu[]},
    reducers: {
        getMenuList: (state: MenuData, action:ActionType)=>{
            return {status: 'finished', data:action.payload};
        }
    }
})
