import React from 'react';
import {createSlice} from '@reduxjs/toolkit';
import {Menu, ImageUrl} from '../../DataTypes/';
type ImagesAction = {
    type: string,
    payload: string
}
type ImageData = {
    status: string,
    data: string[]
}
export const imagesSlice = createSlice({
    name:'imageList',
    initialState: {status: 'loading', data: [] as string[]},
    reducers: {
        getImageList: (state: ImageData, action:ImagesAction)=>{
            return {status: 'finished', data:[...state.data, action.payload]};
        },
        clearImageList:(state:ImageData, action:ImagesAction)=>{
            return {status: 'loading', data:[]};
        }
    }
})
    
