import React, {useState, useEffect, useRef} from 'react';
import { Breadcrumb, Layout, Menu, Form, Input, Button, InputRef } from 'antd';
import {BrowserRouter, Routes, Route, Link} from 'react-router-dom';
import './style.css';
import 'antd/dist/antd.css';
import { Vegetable } from '../../components/Vegetable';
import {Dashboard} from '../../components/Dashboard';
import {useSelector, useDispatch} from 'react-redux';
import {RootState,AppDispatch} from '../../redux/store';
import {getMenus, getListOfImages,clearListOfImages} from '../../redux/actions';
import {ref, listAll, getDownloadURL } from 'firebase/storage';
import {storage} from '../../Config/firebase';
import {useAppDispatch} from '../../Config/hook';

const { Header, Content, Footer} = Layout;
type LayoutType = Parameters<typeof Form>[0]['layout'];

const Main = () => {
  const [form] = Form.useForm();
  const [formLayout, setFormLayout] = useState<LayoutType>('inline');
  //const dispatch = useSelector((c:AppDispatch)=>c=useDispatch());
  const dispatch = useAppDispatch();
    const menus = useSelector((state:RootState)=>state.menuReducer);
    const [header, setHeader] = useState("Trang chủ");
    const [data, setData] = useState('Squash');
    const userEmail = useRef<HTMLInputElement>(null);
    const userPassword = useRef<HTMLInputElement>(null);
    const getEmail = localStorage.getItem("emailData");
    const handleSubmit = ()=>{
      if(userEmail.current != null && userPassword.current != null){
        if(userEmail.current.value=="volodia1917@gmail.com"&&userPassword.current.value=="Nvcmis@1980")
        {
            localStorage.setItem("emailData", "volodia1917@gmail.com");
            localStorage.setItem("passwordData", "Nvcmis@1980");
            window.location.reload();
        }
      }
    }
    
    const handleLogout = () => {
      localStorage.clear();
      window.location.reload();
    }
    useEffect(()=>{
      dispatch(getMenus());
    },[]) 
    return(
        <Layout className="layout">
    <Header style = {{backgroundColor: 'green'}}>
      <div className="logo" />
      <Menu
        style = {{backgroundColor: 'green', color: 'white', fontSize:'20px'}}
        theme='dark'
        mode="horizontal"
        //defaultSelectedKeys={['2']}
        items={menus.data.map((item:any, index:any) => {
          const key = index + 1;
          return {
            key,
            label: item.Caption,
            onClick: async ()=>{
              setData(item.Name);
              await dispatch(clearListOfImages())
              dispatch(getListOfImages({name:item.Name}))
              item.Caption != "Trang chủ" ? setHeader("HÌNH ẢNH VỀ "+item.Caption.toUpperCase()+" TẠI VƯỜN"):setHeader("");
            }
          };
        })}
      >
      </Menu>
      {getEmail?
      <div className="LoginedArea">
        <img src="avartar.jpg" />
      <label>{getEmail}</label><Button className="Logout" type="primary" onClick={handleLogout}>Đăng xuất</Button>
      </div>
      :
      <Form onFinish = {handleSubmit}
      layout={formLayout}
      form={form}
      initialValues={{ layout: formLayout }}
    >   
      <Form.Item label="Tên đăng nhập:">
        <input placeholder="input placeholder" type="text" ref={userEmail} />
      </Form.Item>
      <Form.Item label="Mật khẩu:">
        <input placeholder="input placeholder" type="password" ref={userPassword} />
      </Form.Item>
      <Form.Item>
        <Button type="primary" htmlType='submit'>Đăng nhập</Button>
      </Form.Item>
    </Form>
    }
    </Header>
    <Content style={{ padding: '0 50px' }}>
      <div className="site-layout-content">
        {getEmail?
        <Dashboard />
        :
        <Vegetable title={header} />
      }
      </div>
    </Content>
    <Footer style={{ textAlign: 'center' }}>Demo for Devopp @2025 by nvcmis</Footer>
  </Layout>
    )
}
export default Main;