import React, {useState} from 'react';
import { collection, getDocs } from "firebase/firestore";
import {db} from '../../Config/firebase';
import {Menu} from '../../DataTypes';
import {Dispatch} from 'redux';
import getState from 'redux-thunk';
import {ref, listAll, getDownloadURL, connectStorageEmulator } from 'firebase/storage';
import {storage} from '../../Config/firebase';
import { convertToObject } from 'typescript';
import {VegetableName} from '../../interfaces';
import {imagesSlice} from '../reducers/imageSlice';
import {menuSlice} from '../reducers/menuSlice';

export function getMenus() {
    return async function getMenusThunk(dispatch:Dispatch, getState:any){
        let menusList:Menu[] = [];
        const querySnapshot = await getDocs(collection(db, "Menus"));
querySnapshot.forEach((doc) => {
// doc.data() is never undefined for query doc snapshots
//console.log(doc.id, " => ", doc.data().Submenus);
    menusList.push({Name:doc.data().Name, Caption:doc.data().Caption, Url:doc.data().Url});
})
    //console.log(menusList);
    dispatch(menuSlice.actions.getMenuList(menusList));
    }  
}
export function getListOfImages(data:VegetableName){
    return async function (dispatch: Dispatch, getState:any){
    //let urls:string[] = [];
    const storageRef = await ref(storage, '/' + data.name);
    const res = await listAll(storageRef);
    await res.items.forEach( async (itemRef:any) => {
      let url = await getDownloadURL(itemRef);
      dispatch(imagesSlice.actions.getImageList(url));
      })
    }
}
export function clearListOfImages(){
    return function(dispatch:Dispatch, getState: any){
        dispatch(imagesSlice.actions.clearImageList(''));
        console.log(getState());
    }
}